import jwt from 'jsonwebtoken';
import { randomBytes, timingSafeEqual } from 'node:crypto';

// ── 1. JWT: issue and verify ──────────────────────────────────
const JWT_SECRET = process.env.JWT_SECRET || randomBytes(32).toString('hex');

function issueAccessToken(userId, roles) {
  return jwt.sign(
    { sub: userId, roles },             // Payload (claims)
    JWT_SECRET,
    { expiresIn: '15m', issuer: 'api.example.com', audience: 'web-app' }
  );
}

function verifyAccessToken(token) {
  try {
    return jwt.verify(token, JWT_SECRET, {
      issuer: 'api.example.com',
      audience: 'web-app',
    });                                  // Throws if expired, invalid signature, or wrong issuer/audience
  } catch (err) {
    return null;                         // Return null, never expose error details to client
  }
}

const token = issueAccessToken('user-123', ['editor']);
console.log('Token:', token.split('.')[0] + '...');
console.log('Payload:', verifyAccessToken(token));

// ── 2. RBAC middleware for Express ───────────────────────────
const ROLE_PERMISSIONS = {
  admin:  ['read:any', 'write:any', 'delete:any'],
  editor: ['read:any', 'write:own'],
  viewer: ['read:any'],
};

function requirePermission(permission) {
  return (req, res, next) => {
    const authHeader = req.headers.authorization;
    if (!authHeader?.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Missing or malformed Authorization header' });
    }

    const token = authHeader.slice(7);
    const payload = verifyAccessToken(token);
    if (!payload) return res.status(401).json({ error: 'Invalid or expired token' });

    const userPermissions = (payload.roles || []).flatMap(role => ROLE_PERMISSIONS[role] || []);
    if (!userPermissions.includes(permission)) {
      return res.status(403).json({ error: 'Insufficient permissions' }); // AuthZ failure
    }

    req.user = payload;  // Attach decoded payload for downstream handlers
    next();
  };
}

