// ── 3. OAuth 2.0 state + PKCE generation (for SPA/mobile) ────
import { createHash } from 'node:crypto';

function generatePKCE() {
  const verifier  = randomBytes(32).toString('base64url');          // code_verifier (secret, stored locally)
  const challenge = createHash('sha256').update(verifier).digest('base64url'); // code_challenge (sent to AS)
  const state     = randomBytes(16).toString('hex');                // CSRF protection
  return { verifier, challenge, state };
}

const pkce = generatePKCE();
console.log('PKCE verifier:', pkce.verifier.slice(0, 20) + '...');
console.log('PKCE challenge:', pkce.challenge.slice(0, 20) + '...');

// ── Session vs JWT comparison ─────────────────────────────────
//
// Property          │ Server Session            │ JWT
// ──────────────────┼───────────────────────────┼──────────────────────────
// State location    │ Server (Redis/DB)         │ Client (cookie or memory)
// Revocation        │ Instant (delete session)  │ Wait for expiry (or blacklist)
// Scalability       │ Requires shared store     │ Stateless — any server verifies
// Size              │ Session ID only (~32 bytes)│ 200-500 bytes
// Sensitive data    │ Stored server-side        │ Encoded in token (don't put secrets!)
// Recommended for   │ Traditional web apps      │ APIs, microservices, mobile

// ── JWT anatomy ──────────────────────────────────────────────
const JWT_EXAMPLE = {
  header:  { alg: 'HS256', typ: 'JWT' },
  payload: {
    sub: 'user-123',          // Subject (user ID)
    iss: 'api.example.com',   // Issuer
    aud: 'web-app',           // Audience
    iat: 1700000000,          // Issued At (Unix timestamp)
    exp: 1700000900,          // Expiration (15 min later)
    roles: ['editor'],        // Custom claim
    // NEVER include: passwords, secrets, PII beyond what's needed
  },
  // signature = HMAC-SHA256(base64url(header) + '.' + base64url(payload), secret)
};

// ── OAuth 2.0 grant types and when to use each ───────────────
const OAUTH_FLOWS = {
  'Authorization Code + PKCE': 'Web apps, SPAs, mobile — any user-facing flow (recommended)',
  'Client Credentials':        'Machine-to-machine (backend services, cron jobs — no user)',
  'Device Code':               'TV/CLI/IoT devices with limited input capability',
  'Implicit (DEPRECATED)':     'Never use — tokens exposed in URL fragment; replaced by Auth Code + PKCE',
  'Password (DEPRECATED)':     'Never use — user credentials sent to third-party app',
};

